/* ---------- ledger economico: ultimi 12 mesi, derivato dai cantieri ---------- */
const SEASON = [0.82, 0.9, 1.05, 1.0, 0.95, 1.02, 1.08, 0.88, 1.1, 1.04, 1.0, 1.15];
function buildLedger(): LedgerEntry[] {
  const out: LedgerEntry[] = [];
  const cust = (id: string) => CUSTOMERS.find((c) => c.id === id)!;
  WORKSITES.forEach((w, idx) => {
    if (!w.valoreMensile) return;
    const ratio = w.costoPrevisto / w.valoreMensile;
    for (let back = 11; back >= 0; back--) {
      if (w.stato === 'chiuso' && back < 8) continue; // storico fino alla chiusura
      if (w.stato === 'pianificato') continue;
      const mk = monthKey(-back);
      const jitter = 0.96 + ((idx * 7 + back * 3) % 9) / 100;
      const ricavo = Math.round(w.valoreMensile * SEASON[(11 - back) % 12] * jitter);
      out.push({ id: `${w.id}-${mk}`, mese: mk, customerId: w.customerId, worksiteId: w.id, servizio: w.servizio, regione: cust(w.customerId).regione, ricavo, costo: Math.round(ricavo * ratio) });
    }
  });
  // interventi spot (straordinarie, trattamenti, eventi)
  const SPOT: Array<[number, string, string, string, number, number]> = [
    [-11, 'c2', 'Pulizia straordinaria', 'Veneto', 6200, 4700],
    [-9, 'c5', 'Trattamento pavimenti', 'Lombardia', 4800, 3100],
    [-7, 'c1', 'Pulizia straordinaria', 'Emilia-Romagna', 3900, 2600],
    [-5, 'c3', 'Sanificazione', 'Emilia-Romagna', 5600, 3900],
    [-4, 'c2', 'Pulizia fieristica', 'Veneto', 8900, 7100],
    [-2, 'c5', 'Lavaggio vetrate', 'Lombardia', 3400, 2100],
    [-1, 'c1', 'Sanificazione', 'Emilia-Romagna', 4100, 2900],
    [0, 'c3', 'Sanificazione', 'Emilia-Romagna', 3800, 2650],
  ];
  SPOT.forEach(([back, cid, servizio, regione, ricavo, costo], i) => {
    out.push({ id: `spot-${i}`, mese: monthKey(back as number), customerId: cid as string, worksiteId: null, servizio: servizio as string, regione: regione as string, ricavo: ricavo as number, costo: costo as number });
  });
  return out;
}

